CREATE TABLE IF NOT EXISTS contributions(id INTEGER PRIMARY KEY AUTOINCREMENT,visitor TEXT NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,source TEXT,status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS saved(visitor TEXT NOT NULL,slug TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(visitor,slug));CREATE INDEX IF NOT EXISTS idx_contributions_status ON contributions(status);CREATE INDEX IF NOT EXISTS idx_saved_visitor ON saved(visitor);